interface Session { write(bytes: Uint8Array): void }

function grant(target: Session) {
  const { proxy, revoke } = Proxy.revocable(target, {
    get: (t, p, r) => {
      const v = Reflect.get(t, p, r);
      return typeof v === "function" ? v.bind(t) : v;
    },
  });
  return { capability: proxy as Session, revoke };   // caller sees only the interface
}
